<script setup>
import { computed,ref,onMounted,onBeforeUnmount,nextTick } from 'vue';import { useRoute,useRouter,onBeforeRouteLeave } from 'vue-router';import { studio } from '../store.js';import { evaluateAnswer } from '../services/demo.js';import Icon from '../components/Icon.vue';import Avatar from '../components/Avatar.vue';import {findAudioSample} from '../services/audioSamples.js';
const route=useRoute(),router=useRouter();const s=computed(()=>studio.state.value.sessions.find(x=>x.id===route.params.sessionId));const q=computed(()=>s.value?.questions[s.value.answers.length]);const draft=ref(s.value?.draft||''),error=ref(''),busy=ref(false),voice=ref(s.value?.inputMode==='demo-audio'),inputType=ref(s.value?.draftInputType||'text'),audioId=ref(s.value?.draftAudioSampleId||null),transcriptDialog=ref(),transcript=ref(''),audioError=ref(''),exitDialog=ref(),thread=ref(),root=ref();
const sampleAudio=computed(()=>findAudioSample(q.value?.parentId||q.value?.id));
const feedback=computed(()=>{const a=s.value?.answers.at(-1);return a?evaluateAnswer(s.value.questions.find(x=>x.id===a.questionId),a.text):null});
function save(){if(s.value)studio.call('saveDraft',s.value.id,draft.value,inputType.value,audioId.value)}
async function send(){if(busy.value||!q.value)return;busy.value=true;error.value='';const questionId=q.value.id;try{const result=studio.call('submitAnswer',s.value.id,{questionId,text:draft.value,inputType:inputType.value,audioSampleId:audioId.value});draft.value='';inputType.value='text';audioId.value=null;if(result.status==='completed')router.replace(`/interviews/${s.value.id}/analysis`);else{await nextTick();thread.value?.scrollTo({top:thread.value.scrollHeight,behavior:'smooth'})}}catch(e){error.value=e.message}finally{busy.value=false}}
function sample(){if(!sampleAudio.value)return;transcript.value=sampleAudio.value.text;audioError.value='';transcriptDialog.value.showModal()}
function confirmTranscript(){if(transcript.value.trim().length<8){audioError.value='转写至少保留 8 个字。';return}draft.value=transcript.value;audioId.value=sampleAudio.value.id;inputType.value='demo-voice';save();transcriptDialog.value.close()}
function asText(){inputType.value='text';audioId.value=null;save()}
function pause(){save();studio.call('pauseSession',s.value.id);router.push('/interviews')}
function finish(){try{studio.call('finishSession',s.value.id);router.replace(`/interviews/${s.value.id}/analysis`)}catch(e){error.value=e.message}}
function viewport(){if(root.value)root.value.style.height=`${window.visualViewport?.height||window.innerHeight}px`}
onMounted(async()=>{if(s.value?.status==='completed'){router.replace(`/interviews/${s.value.id}/analysis`);return}if(s.value)studio.call('startSession',s.value.id);viewport();await nextTick();thread.value?.scrollTo({top:thread.value.scrollHeight});window.visualViewport?.addEventListener('resize',viewport);window.addEventListener('resize',viewport)});
onBeforeRouteLeave(()=>{save();if(s.value?.status==='in_progress')studio.call('pauseSession',s.value.id)});onBeforeUnmount(()=>{window.visualViewport?.removeEventListener('resize',viewport);window.removeEventListener('resize',viewport)});
</script>
<template><section v-if="s" ref="root" class="interview-room"><header class="room-header"><button class="icon-button" aria-label="暂停并退出" @click="pause"><Icon name="left"/></button><div><strong>{{s.roleName}} · {{s.focusTopic||'模拟面试'}}</strong><small>{{s.level}} · {{s.mode==='coaching'?'陪练模式':'模拟模式'}} · 进度自动保存</small></div><span class="badge">DEMO</span><button class="button secondary finish-button" @click="exitDialog.showModal()">结束面试</button></header><div class="room-grid"><aside class="room-stages"><p class="eyebrow">INTERVIEW JOURNEY</p><h2>一步一步，清晰表达</h2><ol class="timeline"><li v-for="(item,i) in s.questions" :key="item.id" :class="{current:item.id===q?.id,done:i<s.answers.length}"><span>{{i<s.answers.length?'✓':String(i+1).padStart(2,'0')}}</span><div><h3>{{item.isFollowup?'定向追问':item.stage}}</h3><p>{{item.topic}}</p></div></li></ol><p class="muted small">已回答 {{s.answers.length}} / {{s.questions.length}} 题</p></aside><div class="conversation"><div class="mobile-progress"><span>{{q?.stage}} {{q?.isFollowup?'· 追问':''}}</span><span>{{s.answers.length}} / {{s.questions.length}} 已完成</span></div><div ref="thread" class="message-thread" aria-live="polite"><div class="conversation-intro"><img class="fairy-mascot" src="/images/interview-fairy-transparent.png" alt=""/><h2>你好，我们开始吧。</h2><p>按照自己的节奏，把思路说清楚。</p></div><template v-for="a in s.answers" :key="a.questionId"><article class="question-bubble"><span class="message-label">面试精灵</span><p>{{s.questions.find(x=>x.id===a.questionId)?.text}}</p></article><article class="answer-bubble"><span class="message-label"><Avatar :size="24"/> 你的回答{{a.inputType==='demo-voice'?' · 示例转写':''}}</span><p class="preserve">{{a.text}}</p></article></template><p v-if="feedback&&s.mode==='coaching'" class="feedback"><Icon name="sparkle" :size="18"/>陪练反馈（演示）：{{feedback.advice}}</p><article v-if="q" class="question-bubble current-question"><span class="message-label">面试精灵 · {{q.isFollowup?'追问':q.stage}}</span><h2>{{q.text}}</h2><span class="badge">{{q.topic}}</span></article></div><form class="answer-dock" @submit.prevent="send"><div class="section-heading"><strong>你的回答</strong><button type="button" class="text-link" @click="voice=!voice"><Icon :name="voice?'code':'mic'" :size="18"/>{{voice?'切换文字':'语音演示'}}</button></div><div v-if="voice" class="voice-demo"><span>播放合成示例，核对转写后提交。</span><button type="button" class="button secondary" @click="sample">播放与确认转写</button></div><p v-if="audioId" class="small muted">已关联示例音频，编辑文字不改变原音频。<button type="button" class="text-link" @click="asText">改为纯文字</button></p><label class="sr-only" for="answer">回答当前问题</label><textarea id="answer" v-model="draft" @input="save" maxlength="8000" rows="3" placeholder="先说结论，再展开你的思路与具体例子…"/><div class="dock-actions"><span class="muted small">{{draft.length}} / 8000 · 至少 8 字</span><button class="button primary" :disabled="busy||draft.trim().length<8" type="submit">提交回答 <Icon name="send" :size="20"/></button></div><p v-if="error" role="alert" class="error">{{error}}</p></form></div><aside class="room-hints"><span class="badge">本轮考察</span><h3>{{q?.topic}}</h3><p>先说明判断依据，再解释方案与取舍。</p><hr><h3>表达小提示</h3><p>背景 → 行动 → 结果</p><p class="muted">遇到不熟悉的问题，可以坦诚说明假设，再给出分析路径。</p><p class="notice">演示题库与规则反馈，不调用真实 AI 或录音服务。</p></aside></div><dialog ref="transcriptDialog" class="transcript-dialog"><h2>确认示例转写</h2><span class="badge">合成音频 · 不是你的录音</span><p class="small muted">{{q?.isFollowup?'这是同主题参考示例，可根据追问修改转写；音频保留原文。':'播放后核对文字，可编辑再提交。'}}</p><audio v-if="sampleAudio" controls :src="sampleAudio.file" preload="metadata" @error="audioError='音频加载失败，请取消并使用文字回答。'"/><label>转写内容<textarea v-model="transcript" rows="5" maxlength="8000"/></label><p v-if="audioError" class="error" role="alert">{{audioError}}</p><div class="action-bar"><button class="button secondary" @click="transcriptDialog.close()">取消</button><button class="button primary" :disabled="!!audioError" @click="confirmTranscript">确认并填入回答</button></div></dialog><dialog ref="exitDialog"><h2>结束这次面试？</h2><p>已提交的 {{s.answers.length}} 道回答会生成报告，未提交的草稿不会参与评分。</p><div class="stack"><button class="button primary" :disabled="!s.answers.length" @click="finish">结束并生成报告</button><button class="button secondary" @click="pause">保存进度，稍后继续</button><button class="text-link" @click="exitDialog.close()">返回面试</button></div></dialog></section><section v-else class="card empty"><h1>会话不存在</h1><RouterLink to="/interviews">返回面试记录</RouterLink></section></template>
